class Base {
public:
    int x;
};
class Derived : public Base {
public:
    void setX(int value) { x = value; }
};
int main() {
    Derived d;
    d.setX(5);
    return 0;
}

class Base {
public:
    virtual void show() { cout << "Base"; }
};
class Derived : public Base {
public:
    void show() override { cout << "Derived"; }
};
int main() {
    Base *ptr = new Derived();
    ptr->show();
    return 0;
}

